// IDP — extraction structurée des champs de facture (fallback déterministe)
const out = [];
for (const item of $input.all()) {
  const text = item.json.text || item.json.data || '';
  const grab = (re) => { const m = text.match(re); return m ? m[1].trim() : ''; };

  const fournisseur = grab(/Émetteur\s*:?[\s\n]*([A-Z][^\n]+)/);
  const numero      = grab(/Facture\s*n°\s*:?\s*([A-Z0-9-]+)/i);
  const date        = grab(/Date\s*:?\s*(\d{2}\/\d{2}\/\d{4})/);
  const ttcStr      = grab(/Total\s*TTC\s*:?\s*([\d\s\u00A0]+,\d{2})/i);
  const htStr       = grab(/Total\s*HT\s*:?\s*([\d\s\u00A0]+,\d{2})/i) || grab(/([\d\s\u00A0]+,\d{2})\s*€?\s*HT/i);
  const tvaStr      = grab(/TVA\s*\(20\s*%\)\s*:?\s*([\d\s\u00A0]+,\d{2})/i);

  const toNum = (s) => parseFloat((s || '').replace(/[\s\u00A0]/g, '').replace(',', '.')) || 0;
  const montant_ttc = toNum(ttcStr);

  out.push({
    json: {
      fichier: (item.binary && item.binary.data && item.binary.data.fileName) || numero || 'inconnu',
      fournisseur,
      numero,
      date,
      montant_ht: toNum(htStr),
      tva: toNum(tvaStr),
      montant_ttc,
      route: montant_ttc > 1000 ? 'validation humaine' : 'paiement auto',
      extraction_ok: montant_ttc > 0
    }
  });
}
return out;
